create table if not exists profiles (id uuid primary key, display_name text, role text check (role in ('customer','worker','both')), city text, bio text, verified boolean default false, rating numeric default 0, created_at timestamptz default now());
create table if not exists categories (id bigserial primary key, name text unique not null, active boolean default true);
create table if not exists requests (id uuid primary key default gen_random_uuid(), customer_id uuid, category_id bigint references categories(id), title text not null, description text, location text, budget numeric, status text default 'open', created_at timestamptz default now());
create table if not exists offers (id uuid primary key default gen_random_uuid(), request_id uuid references requests(id) on delete cascade, worker_id uuid, amount numeric, message text, status text default 'pending', created_at timestamptz default now());
create table if not exists bookings (id uuid primary key default gen_random_uuid(), request_id uuid references requests(id), worker_id uuid, customer_id uuid, amount numeric, status text default 'booked', created_at timestamptz default now());
create table if not exists memberships (id bigserial primary key, name text unique, monthly_price numeric, customer_fee_discount numeric default 0, worker_commission_discount numeric default 0, active boolean default true);
create table if not exists subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid, membership_id bigint references memberships(id), status text default 'active', stripe_subscription_id text, created_at timestamptz default now());
create table if not exists reviews (id uuid primary key default gen_random_uuid(), booking_id uuid references bookings(id), reviewer_id uuid, reviewee_id uuid, rating int check(rating between 1 and 5), comment text, created_at timestamptz default now());
create table if not exists reports (id uuid primary key default gen_random_uuid(), reporter_id uuid, target_user_id uuid, booking_id uuid, reason text, status text default 'open', created_at timestamptz default now());
